from collections import Counter
def longest_k(s, k):
    window, left, best = Counter(), 0, 0
    for right, ch in enumerate(s):
        window[ch] += 1
        while len(window) > k:
            window[s[left]] -= 1
            if window[s[left]] == 0:
                del window[s[left]]
            left += 1
        best = max(best, right - left + 1)
    return best

