import time

def fetch(get, url, attempts=3, sleep=time.sleep):
    for i in range(attempts):
        r = get(url)
        if not (r.status == 429 or r.status >= 500):
            return r
        if i < attempts - 1:
            sleep(0.5 * 2 ** i)
    raise RuntimeError(f"gave up after {attempts} attempts: {r.status}")

