    out = pack_chunks(["a b", "c d e"], 5, words)
    assert out == ["a b", "c d e"], f"5 tokens fit a budget of 5; got {out}"

def test_over_budget():
    assert pack_chunks(["a b", "c d e", "f"], 4, words) == ["a b"]

def test_empty():
    assert pack_chunks([], 10, words) == []

