def assemble(events):
    blocks, stop = {}, None
    for ev in events:
        if ev["type"] == "content_block_start":
            blocks[ev["index"]] = ""
        elif ev["type"] == "content_block_delta":
            blocks[ev["index"]] += ev["delta"]["text"]
